using Dapper;
using Sigov.Application.Common;
using Sigov.Application.OrdemServico;
using Sigov.Domain.OrdemServico;
using Sigov.Infrastructure.Persistence.Dapper;

namespace Sigov.Infrastructure.OrdemServico;

public sealed class OrdemServicoRepository(NpgsqlConnectionFactory factory) : IOrdemServicoRepository
{
    public async Task<PagedResult<OrdemServicoResumoDto>> ListarAsync(Guid t, OrdemServicoFiltro f, CancellationToken ct)
    {
        var p=Math.Max(1,f.Pagina); var s=Math.Clamp(f.Tamanho,1,100); const string sql="select count(*) from sigov.os_ordem_servico o where tenant_id=@t and not is_deleted and (not @hs or status=@status) and (not @hb or numero ilike @term or cliente_nome ilike @term) and (@tecnico is null or tecnico_id=@tecnico); select id,numero,cliente_nome Cliente,status,prioridade,agendada_inicio AgendadaInicio,tecnico_id TecnicoId,version from sigov.os_ordem_servico where tenant_id=@t and not is_deleted and (not @hs or status=@status) and (not @hb or numero ilike @term or cliente_nome ilike @term) and (@tecnico is null or tecnico_id=@tecnico) order by prioridade desc,created_at desc offset @off limit @s";
        await using var c=factory.CreateConnection(); using var m=await c.QueryMultipleAsync(new CommandDefinition(sql,new{t,hs=!string.IsNullOrWhiteSpace(f.Status),status=f.Status?.ToUpperInvariant(),hb=!string.IsNullOrWhiteSpace(f.Busca),term=$"%{f.Busca}%",tecnico=f.TecnicoId,off=(p-1)*s,s},cancellationToken:ct)); var total=await m.ReadSingleAsync<long>(); return new((await m.ReadAsync<OrdemServicoResumoDto>()).AsList(),p,s,total);
    }
    public async Task<OrdemServicoDetalheDto?> ObterAsync(Guid t,Guid id,CancellationToken ct){const string q="select id,numero,cliente_id ClienteId,cliente_nome Cliente,status,prioridade,origem,descricao,endereco,pedido_id PedidoId,proposta_id PropostaId,tecnico_id TecnicoId,agendada_inicio AgendadaInicio,agendada_fim AgendadaFim,inicio_real InicioReal,conclusao_em ConclusaoEm,custo_real CustoReal,version from sigov.os_ordem_servico where tenant_id=@t and id=@id and not is_deleted; select id,descricao,quantidade,unidade,executado,justificativa from sigov.os_item where tenant_id=@t and ordem_servico_id=@id and not is_deleted order by ordem";await using var c=factory.CreateConnection();using var m=await c.QueryMultipleAsync(new CommandDefinition(q,new{t,id},cancellationToken:ct));var x=await m.ReadSingleOrDefaultAsync<OrdemServicoDetalheDto>();return x is null?null:x with{Itens=(await m.ReadAsync<OrdemServicoItemDto>()).AsList()};}
    public async Task<Guid> CriarAsync(Guid t,Guid u,CriarOrdemServicoRequest r,string key,string corr,CancellationToken ct){await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);var old=await c.ExecuteScalarAsync<Guid?>(new CommandDefinition("select recurso_id from sigov.os_idempotencia where tenant_id=@t and operacao='CRIAR' and chave=@key",new{t,key},tx,cancellationToken:ct));if(old.HasValue)return old.Value;var cliente=await c.ExecuteScalarAsync<string?>(new CommandDefinition("select nome from sigov.enterprise_cliente where tenant_id=@t and id=@ClienteId and not is_deleted",new{t,r.ClienteId},tx,cancellationToken:ct))??throw new InvalidOperationException("Cliente não encontrado.");var seq=await Numero(c,tx,t,ct);var id=Guid.NewGuid();await c.ExecuteAsync(new CommandDefinition("insert into sigov.os_ordem_servico(id,tenant_id,numero,cliente_id,cliente_nome,status,prioridade,origem,descricao,endereco,prazo_sla,created_by,updated_by,correlation_id) values(@id,@t,@numero,@ClienteId,@cliente,'ABERTA',@prioridade,'MANUAL',@Descricao,@Endereco,@PrazoSla,@us,@us,@corr);insert into sigov.os_status_historico(tenant_id,ordem_servico_id,status_novo,created_by,updated_by,correlation_id) values(@t,@id,'ABERTA',@us,@us,@corr);insert into sigov.os_idempotencia(tenant_id,operacao,chave,recurso_id,created_by,updated_by,correlation_id) values(@t,'CRIAR',@key,@id,@us,@us,@corr)",new{id,t,numero,r.ClienteId,cliente,prioridade=r.Prioridade.ToUpperInvariant(),r.Descricao,r.Endereco,r.PrazoSla,us=u.ToString(),corr},tx,cancellationToken:ct));await tx.CommitAsync(ct);return id;}
    public async Task<Guid> GerarDoPedidoAsync(Guid t,Guid u,Guid pedidoId,string key,string corr,CancellationToken ct){await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);var old=await c.ExecuteScalarAsync<Guid?>(new CommandDefinition("select recurso_id from sigov.os_idempotencia where tenant_id=@t and operacao='PEDIDO' and chave=@key",new{t,key},tx,cancellationToken:ct));if(old.HasValue){await tx.CommitAsync(ct);return old.Value;}var p=await c.QuerySingleOrDefaultAsync<(string Status,Guid ClienteId,Guid PropostaId,string Cliente,string? Observacao,DateTimeOffset? Previsao)>(new CommandDefinition("select p.status,p.cliente_id ClienteId,p.proposta_id PropostaId,c.nome Cliente,p.observacao,p.previsao_entrega Previsao from sigov.enterprise_pedido_venda p join sigov.enterprise_cliente c on c.tenant_id=p.tenant_id and c.id=p.cliente_id where p.tenant_id=@t and p.id=@pedidoId and not p.is_deleted for update",new{t,pedidoId},tx,cancellationToken:ct));if(p==default)throw new InvalidOperationException("Pedido não encontrado.");if(p.Status!="CONFIRMADO")throw new InvalidOperationException("Somente pedido confirmado pode gerar OS.");var linked=await c.ExecuteScalarAsync<Guid?>(new CommandDefinition("select ordem_servico_id from sigov.enterprise_pedido_venda where tenant_id=@t and id=@pedidoId",new{t,pedidoId},tx,cancellationToken:ct));if(linked.HasValue){await tx.CommitAsync(ct);return linked.Value;}var id=Guid.NewGuid();var numero=await Numero(c,tx,t,ct);await c.ExecuteAsync(new CommandDefinition("insert into sigov.os_ordem_servico(id,tenant_id,numero,cliente_id,cliente_nome,pedido_id,proposta_id,status,prioridade,origem,descricao,prazo_sla,created_by,updated_by,correlation_id) values(@id,@t,@numero,@ClienteId,@Cliente,@pedidoId,@PropostaId,'EM_TRIAGEM','NORMAL','PEDIDO_COMERCIAL',coalesce(@Observacao,'Atendimento originado pelo pedido'),@Previsao,@us,@us,@corr); insert into sigov.os_item(tenant_id,ordem_servico_id,descricao,quantidade,unidade,ordem,created_by,updated_by,correlation_id) select i.tenant_id,@id,i.descricao,i.quantidade,i.unidade,row_number() over(order by i.id),@us,@us,@corr from sigov.enterprise_pedido_venda_item i where i.tenant_id=@t and i.pedido_id=@pedidoId and not i.is_deleted; update sigov.enterprise_pedido_venda set ordem_servico_id=@id,requer_ordem_servico=true,updated_by=@us,correlation_id=@corr where tenant_id=@t and id=@pedidoId; insert into sigov.os_status_historico(tenant_id,ordem_servico_id,status_novo,observacao,created_by,updated_by,correlation_id) values(@t,@id,'EM_TRIAGEM','Gerada pelo pedido',@us,@us,@corr); insert into sigov.os_idempotencia(tenant_id,operacao,chave,recurso_id,created_by,updated_by,correlation_id) values(@t,'PEDIDO',@key,@id,@us,@us,@corr); insert into sigov.integracao_outbox(id,tenant_id,tipo_evento,aggregate_id,payload,created_at) values(gen_random_uuid(),@t,'ordem_servico.criada_por_pedido',@id,jsonb_build_object('ordemServicoId',@id,'pedidoId',@pedidoId),now())",new{id,t,numero,p.ClienteId,p.Cliente,pedidoId,p.PropostaId,p.Observacao,p.Previsao,us=u.ToString(),corr},tx,cancellationToken:ct));await tx.CommitAsync(ct);return id;}
    private static async Task<string> Numero(System.Data.IDbConnection c,System.Data.IDbTransaction tx,Guid t,CancellationToken ct){var n=await c.ExecuteScalarAsync<long>(new CommandDefinition("insert into sigov.os_numeracao(tenant_id,ano,ultimo_numero) values(@t,extract(year from current_date)::int,1) on conflict(tenant_id,ano) do update set ultimo_numero=sigov.os_numeracao.ultimo_numero+1,updated_at=now() returning ultimo_numero",new{t},tx,cancellationToken:ct));return $"OS-{DateTime.UtcNow:yyyy}-{n:000000}";}
    public Task AtribuirAsync(Guid t,Guid u,Guid id,AtribuirTecnicoRequest r,string corr,CancellationToken ct)=>Update(t,u,id,r.Version,"tecnico_id=@TecnicoId,equipe_id=@EquipeId",new{r.TecnicoId,r.EquipeId},corr,ct);
    public async Task AgendarAsync(Guid t,Guid u,Guid id,AgendarOrdemServicoRequest r,string corr,CancellationToken ct){await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);var conflito=await c.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from sigov.os_agendamento where tenant_id=@t and tecnico_id=@TecnicoId and not is_deleted and inicio<@Fim and fim>@Inicio and ordem_servico_id<>@id)",new{t,id,r.TecnicoId,r.Inicio,r.Fim},tx,cancellationToken:ct));if(conflito&&(!r.AutorizarConflito||string.IsNullOrWhiteSpace(r.Justificativa)))throw new InvalidOperationException("Conflito de agenda. Autorização e justificativa são obrigatórias.");var n=await c.ExecuteAsync(new CommandDefinition("insert into sigov.os_agendamento(tenant_id,ordem_servico_id,tecnico_id,equipe_id,inicio,fim,janela,observacao,conflito_autorizado,justificativa_conflito,created_by,updated_by,correlation_id) values(@t,@id,@TecnicoId,@EquipeId,@Inicio,@Fim,@Janela,@Observacao,@AutorizarConflito,@Justificativa,@us,@us,@corr);update sigov.os_ordem_servico set tecnico_id=coalesce(@TecnicoId,tecnico_id),equipe_id=coalesce(@EquipeId,equipe_id),agendada_inicio=@Inicio,agendada_fim=@Fim,status='AGENDADA',version=version+1,updated_by=@us,correlation_id=@corr where tenant_id=@t and id=@id and version=@Version and status not in('CONCLUIDA','CANCELADA')",new{t,id,r.TecnicoId,r.EquipeId,r.Inicio,r.Fim,r.Janela,r.Observacao,r.AutorizarConflito,r.Justificativa,r.Version,us=u.ToString(),corr},tx,cancellationToken:ct));if(n!=2)throw new InvalidOperationException("OS alterada por outro usuário.");await tx.CommitAsync(ct);}
    public async Task TransicionarAsync(Guid t,Guid u,Guid id,string destino,long version,string? motivo,DateTimeOffset? inicio,string corr,CancellationToken ct){await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);var atual=await c.QuerySingleOrDefaultAsync<(string Status,Guid? TecnicoId)>(new CommandDefinition("select status,tecnico_id TecnicoId from sigov.os_ordem_servico where tenant_id=@t and id=@id and not is_deleted for update",new{t,id},tx,cancellationToken:ct));if(atual==default)throw new InvalidOperationException("OS não encontrada.");var a=Enum.Parse<OrdemServicoStatus>(atual.Status.Replace("_",""),true);var d=Enum.Parse<OrdemServicoStatus>(destino.Replace("_",""),true);OrdemServicoRules.ValidarTransicao(a,d);if(d is OrdemServicoStatus.EmExecucao or OrdemServicoStatus.EmDeslocamento && !atual.TecnicoId.HasValue)throw new InvalidOperationException("Técnico responsável é obrigatório.");if(d==OrdemServicoStatus.EmExecucao&&inicio is null)throw new InvalidOperationException("Data real de início é obrigatória.");if(d==OrdemServicoStatus.Pausada&&string.IsNullOrWhiteSpace(motivo))throw new InvalidOperationException("Motivo da pausa é obrigatório.");if(d==OrdemServicoStatus.Concluida){var pendente=await c.ExecuteScalarAsync<bool>(new CommandDefinition("select exists(select 1 from sigov.os_checklist_instancia where tenant_id=@t and ordem_servico_id=@id and obrigatorio and bloqueia_conclusao and not respondido) or exists(select 1 from sigov.os_apontamento where tenant_id=@t and ordem_servico_id=@id and fim is null and not is_deleted)",new{t,id},tx,cancellationToken:ct));if(pendente)throw new InvalidOperationException("Checklist obrigatório ou apontamento aberto impede a conclusão.");}var n=await c.ExecuteAsync(new CommandDefinition("update sigov.os_ordem_servico set status=@destino,inicio_real=coalesce(inicio_real,@inicio),conclusao_em=case when @destino='CONCLUIDA' then now() else conclusao_em end,version=version+1,updated_by=@us,correlation_id=@corr where tenant_id=@t and id=@id and version=@version;insert into sigov.os_status_historico(tenant_id,ordem_servico_id,status_anterior,status_novo,observacao,created_by,updated_by,correlation_id) values(@t,@id,@status,@destino,@motivo,@us,@us,@corr)",new{t,id,destino=destino.ToUpperInvariant(),inicio,version,status=atual.Status,motivo,us=u.ToString(),corr},tx,cancellationToken:ct));if(n!=2)throw new InvalidOperationException("Conflito de versão.");await tx.CommitAsync(ct);}
    public async Task<IReadOnlyList<OrdemServicoAgendaDto>> AgendaAsync(Guid t,DateTimeOffset i,DateTimeOffset f,Guid? tecnico,CancellationToken ct){const string q="select o.id,o.numero,o.cliente_nome Cliente,o.prioridade,o.status,a.tecnico_id TecnicoId,a.inicio,a.fim,o.endereco from sigov.os_agendamento a join sigov.os_ordem_servico o on o.tenant_id=a.tenant_id and o.id=a.ordem_servico_id where a.tenant_id=@t and not a.is_deleted and a.inicio<@f and a.fim>@i and (@tecnico is null or a.tecnico_id=@tecnico) order by a.inicio";await using var c=factory.CreateConnection();return (await c.QueryAsync<OrdemServicoAgendaDto>(new CommandDefinition(q,new{t,i,f,tecnico},cancellationToken:ct))).AsList();}
    public async Task<IReadOnlyList<OrdemServicoChecklistDto>> ChecklistAsync(Guid t,Guid id,CancellationToken ct){await using var c=factory.CreateConnection();return (await c.QueryAsync<OrdemServicoChecklistDto>(new CommandDefinition("select id,titulo,tipo,obrigatorio,respondido,resposta,bloqueia_conclusao BloqueiaConclusao from sigov.os_checklist_instancia where tenant_id=@t and ordem_servico_id=@id order by ordem",new{t,id},cancellationToken:ct))).AsList();}
    public async Task ResponderChecklistAsync(Guid t,Guid u,Guid id,ResponderChecklistRequest r,string corr,CancellationToken ct){await using var c=factory.CreateConnection();var n=await c.ExecuteAsync(new CommandDefinition("update sigov.os_checklist_instancia set resposta=@Resposta,observacao_resposta=@Observacao,evidencia_id=@EvidenciaId,respondido=true,respondido_em=now(),version=version+1,updated_by=@us,correlation_id=@corr where tenant_id=@t and ordem_servico_id=@id and id=@ItemId and version=@Version",new{t,id,r.ItemId,r.Resposta,r.Observacao,r.EvidenciaId,r.Version,us=u.ToString(),corr},cancellationToken:ct));if(n!=1)throw new InvalidOperationException("Item não encontrado ou versão desatualizada.");}
    public async Task<IReadOnlyList<OrdemServicoApontamentoDto>> ApontamentosAsync(Guid t,Guid id,CancellationToken ct){await using var c=factory.CreateConnection();return(await c.QueryAsync<OrdemServicoApontamentoDto>(new CommandDefinition("select id,tecnico_id TecnicoId,atividade,inicio,fim,intervalo_minutos IntervaloMinutos from sigov.os_apontamento where tenant_id=@t and ordem_servico_id=@id and not is_deleted order by inicio",new{t,id},cancellationToken:ct))).AsList();}
    public async Task RegistrarApontamentoAsync(Guid t,Guid u,Guid id,RegistrarApontamentoRequest r,string key,string corr,CancellationToken ct){await using var c=factory.CreateConnection();var n=await c.ExecuteAsync(new CommandDefinition("insert into sigov.os_apontamento(tenant_id,ordem_servico_id,tecnico_id,atividade,inicio,fim,intervalo_minutos,observacao,idempotency_key,created_by,updated_by,correlation_id) values(@t,@id,@TecnicoId,@Atividade,@Inicio,@Fim,@IntervaloMinutos,@Observacao,@key,@us,@us,@corr) on conflict(tenant_id,idempotency_key) do nothing",new{t,id,r.TecnicoId,r.Atividade,r.Inicio,r.Fim,r.IntervaloMinutos,r.Observacao,key,us=u.ToString(),corr},cancellationToken:ct));if(n!=1)throw new InvalidOperationException("Apontamento duplicado.");}
    public async Task<IReadOnlyList<OrdemServicoConsumoDto>> PecasAsync(Guid t,Guid id,CancellationToken ct){await using var c=factory.CreateConnection();return(await c.QueryAsync<OrdemServicoConsumoDto>(new CommandDefinition("select id,produto_id ProdutoId,quantidade,custo_unitario CustoUnitario,quantidade_devolvida QuantidadeDevolvida from sigov.os_consumo_peca where tenant_id=@t and ordem_servico_id=@id and not is_deleted",new{t,id},cancellationToken:ct))).AsList();}
    public async Task ConsumirAsync(Guid t,Guid u,Guid id,ConsumirPecaRequest r,string key,string corr,CancellationToken ct){await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);var saldo=await c.QuerySingleOrDefaultAsync<(decimal Quantidade,decimal CustoMedio)>(new CommandDefinition("select quantidade,custo_medio CustoMedio from sigov.enterprise_estoque_saldo where tenant_id=@t and produto_id=@ProdutoId and almoxarifado_id=@AlmoxarifadoId and not is_deleted for update",new{t,r.ProdutoId,r.AlmoxarifadoId},tx,cancellationToken:ct));if(saldo==default||saldo.Quantidade<r.Quantidade&&!r.AutorizarSaldoNegativo)throw new InvalidOperationException("Saldo insuficiente.");var n=await c.ExecuteAsync(new CommandDefinition("update sigov.enterprise_estoque_saldo set quantidade=quantidade-@Quantidade,version=version+1,updated_at=now() where tenant_id=@t and produto_id=@ProdutoId and almoxarifado_id=@AlmoxarifadoId;insert into sigov.os_consumo_peca(tenant_id,ordem_servico_id,produto_id,almoxarifado_id,quantidade,custo_unitario,idempotency_key,created_by,updated_by,correlation_id) values(@t,@id,@ProdutoId,@AlmoxarifadoId,@Quantidade,@custo,@key,@us,@us,@corr) on conflict(tenant_id,idempotency_key) do nothing",new{t,id,r.ProdutoId,r.AlmoxarifadoId,r.Quantidade,custo=saldo.CustoMedio,key,us=u.ToString(),corr},tx,cancellationToken:ct));if(n!=2)throw new InvalidOperationException("Consumo duplicado ou saldo não atualizado.");await tx.CommitAsync(ct);}
    public async Task DevolverAsync(Guid t,Guid u,Guid id,DevolverPecaRequest r,string key,string corr,CancellationToken ct){await using var c=factory.CreateConnection();await c.OpenAsync(ct);await using var tx=await c.BeginTransactionAsync(ct);var x=await c.QuerySingleOrDefaultAsync<(Guid ProdutoId,Guid AlmoxarifadoId,decimal Quantidade,decimal QuantidadeDevolvida)>(new CommandDefinition("select produto_id ProdutoId,almoxarifado_id AlmoxarifadoId,quantidade,quantidade_devolvida QuantidadeDevolvida from sigov.os_consumo_peca where tenant_id=@t and ordem_servico_id=@id and id=@ConsumoId for update",new{t,id,r.ConsumoId},tx,cancellationToken:ct));if(x==default||x.Quantidade-x.QuantidadeDevolvida<r.Quantidade)throw new InvalidOperationException("Quantidade de devolução excede o consumo.");var n=await c.ExecuteAsync(new CommandDefinition("insert into sigov.os_devolucao_peca(tenant_id,ordem_servico_id,consumo_id,produto_id,almoxarifado_id,quantidade,motivo,idempotency_key,created_by,updated_by,correlation_id) values(@t,@id,@ConsumoId,@ProdutoId,@AlmoxarifadoId,@Quantidade,@Motivo,@key,@us,@us,@corr) on conflict(tenant_id,idempotency_key) do nothing;update sigov.os_consumo_peca set quantidade_devolvida=quantidade_devolvida+@Quantidade,version=version+1 where tenant_id=@t and id=@ConsumoId;update sigov.enterprise_estoque_saldo set quantidade=quantidade+@Quantidade,version=version+1 where tenant_id=@t and produto_id=@ProdutoId and almoxarifado_id=@AlmoxarifadoId",new{t,id,r.ConsumoId,x.ProdutoId,x.AlmoxarifadoId,r.Quantidade,r.Motivo,key,us=u.ToString(),corr},tx,cancellationToken:ct));if(n!=3)throw new InvalidOperationException("Devolução não persistida integralmente.");await tx.CommitAsync(ct);}
    public async Task<OrdemServicoDashboardDto> DashboardAsync(Guid t,CancellationToken ct){await using var c=factory.CreateConnection();return await c.QuerySingleAsync<OrdemServicoDashboardDto>(new CommandDefinition("select count(*) filter(where status='ABERTA') Abertas,count(*) filter(where status='EM_TRIAGEM') Triagem,count(*) filter(where status='AGENDADA') Agendadas,count(*) filter(where status='EM_EXECUCAO') Execucao,count(*) filter(where status='PAUSADA') Pausadas,count(*) filter(where status='AGUARDANDO_PECA') AguardandoPeca,count(*) filter(where prazo_sla<now() and status not in('CONCLUIDA','CANCELADA')) Vencidas,count(*) filter(where status='CONCLUIDA') Concluidas,count(*) filter(where status='CANCELADA') Canceladas,coalesce(avg(custo_real) filter(where status='CONCLUIDA'),0) CustoMedio from sigov.os_ordem_servico where tenant_id=@t and not is_deleted",new{t},cancellationToken:ct));}
    private async Task Update(Guid t,Guid u,Guid id,long version,string set,object values,string corr,CancellationToken ct){await using var c=factory.CreateConnection();var args=new DynamicParameters(values);args.Add("t",t);args.Add("id",id);args.Add("version",version);args.Add("us",u.ToString());args.Add("corr",corr);var n=await c.ExecuteAsync(new CommandDefinition($"update sigov.os_ordem_servico set {set},version=version+1,updated_at=now(),updated_by=@us,correlation_id=@corr where tenant_id=@t and id=@id and version=@version and status not in('CONCLUIDA','CANCELADA')",args,cancellationToken:ct));if(n!=1)throw new InvalidOperationException("OS não encontrada ou versão desatualizada.");}
}
